export const edition='2026-09-25';
export const categories={architecture:'Архитектура',interiors:'Интерьеры',objects:'Предметы',furniture:'Мебель',lighting:'Свет',materials:'Материалы',technology:'Технологии',exhibitions:'Выставки',people:'Люди и бюро'};
import {photoLegacyArticles} from './editorial/photo-legacy.mjs';
export const articles=[...photoLegacyArticles];
const defaultArticleDate='2026-09-14';
const add=(id,title,category,format,place,dek,body,source,credit='',image=id,event='',date=defaultArticleDate)=>articles.push({id,title,category,format,place,dek,body:body.split('\n\n'),source,credit,image,event,date,author:'Редакция TECTONICA'});
add('danshuis','MAD превращает склад 1923 года в дом для танца','architecture','Главная история','Роттердам, Нидерланды','Четырнадцать студий, открытая сцена и зал на крыше — в бывшем портовом складе у Мааса.',`У танцевального центра Danshuis будет адрес с промышленным прошлым: склад в стиле ар-деко на южном берегу Мааса. MAD и EGM работают с существующим зданием площадью 9 500 м². Подробный проект представили 1 сентября; открытие запланировано на 2030 год.\n\nВнутри разместят четырнадцать танцевальных студий, спортзал, выставочное пространство, кафе и открытую сцену. Зал Salle des Fêtes на крыше предназначен для крупных публичных событий. Этажи свяжет вертикальное фойе, а наружные пространства будут обращены к набережной.\n\nЦентр рассчитан и на профессионалов, и на любителей разных возрастов. Его сосед — музей миграции Fenix, также спроектированный MAD. Оба проекта связаны с фондом Droom en Daad.\n\nЗдесь интересно распределение функций: повседневные занятия занимают одно здание с публичной программой. Посетитель сможет прийти на тренировку, выставку или встречу, а не только на вечерний спектакль. Насколько открытым окажется это соседство, станет понятно после запуска: пока перед нами визуализация и заявленная программа.`,'https://danshuis.nl/nl/ma-yansongmad-designs-revealed-for-rotterdams-centre-for-dance-danshuis/','Проект: MAD · Визуализация: Proloog · Источник: Danshuis','danshuis','Представлен 1 сентября 2026 · Открытие планируется в 2030');
add('johnny','Фэй Тугуд сделала светильники, которые можно мять','lighting','Главная история','Лондон, Великобритания','Бумажная оболочка Johnny меняет силуэт от прикосновения. Под ней — стальной каркас.',`Новую серию Johnny Фэй Тугуд показывает в своей студии в лондонском Боро 14 и 15 сентября. Бумагу для абажуров вручную вырезают и сшивают английские мастера, затем натягивают на стальной каркас. Складки можно поправлять руками: вместе с ними меняются контур предмета и рисунок теней.\n\nВ коллекции три типа светильников: подвесной, напольный и настольный. У напольной версии — кованые стальные ножки с вручную обработанными шарообразными окончаниями. Настольная напоминает уменьшенный макет той же конструкции.\n\nПри выключенном свете бумага выглядит плотной и скульптурной. Когда лампа загорается, оболочка становится полупрозрачной и обнаруживает швы и каркас. Тугуд работает с двумя состояниями одного предмета: дневным и вечерним.\n\nИмя возникло ещё у прототипов. Высокие бумажные формы напомнили сотрудникам студии гигантские презервативы; Johnny — одно из их британских разговорных названий. Внутренняя шутка осталась названием коллекции.\n\nПоказ проходит по адресу 48A Union Street, с 9:30 до 17:30. Вход свободный.`,'https://londondesignfestival.com/activities/johnny','Johnny, Faye Toogood · Изображение из официальной программы London Design Festival','johnny','14–15 сентября 2026');
add('baiwu','В Юньнани зернохранилища стали книжным магазином','architecture','Проект','Байу, Китай','Jiakun Architects сохранили земляные стены, но сняли с них нагрузку.',`Два заброшенных зернохранилища в деревне Байу стали книжным магазином Librairie Avant-Garde. Их земляные стены уже не могли работать как несущие, а крыши пришли в негодность. Jiakun Architects оставили старые стены как память о месте и ввели внутрь самостоятельную конструкцию из прессованного бамбука.\n\nНовый каркас несёт здание независимо от исторической оболочки. Тот же материал использован для стеллажей и выставочных элементов — интерьер продолжает конструктивную логику.\n\nДва объёма соединяет крытая галерея. Между ними появился террасированный сад: нижняя часть работает как площадка для выступлений, верхняя — как место для обзора. Пространство предназначено и для покупателей, и для жителей деревни.\n\nЗемляные стены укрепили и покрыли золотой краской. Архитекторы связывают цвет с историей региона и перевозкой меди. Получилось заметное современное вмешательство, которое оставляет старому зданию узнаваемую материальность.\n\nПлощадь проекта — 670 м². Он завершён в 2025 году; новая публикация с фотографиями вышла 9 сентября 2026-го.`,'https://www.archdaily.com/1184708/librairie-avant-garde-huize-baiwu-bookstore-jiakun-architects','Фото: Arch-Exist · Проект: Jiakun Architects · ArchDaily','baiwu','Построено в 2025 · Публикация источника 9 сентября 2026');
add('sa-casa','На Ибице спроектировали около 190 доступных квартир из дерева','architecture','Новость','Ибица, Испания','Sa Casa от Stefano Boeri Architetti — четыре корпуса вокруг общего зелёного пространства.',`Бюро Stefano Boeri Architetti представило Sa Casa — жилой комплекс для испанского государственного заказчика Casa 47. Около 190 квартир с регулируемой арендной платой распределены между четырьмя корпусами. В центре — открытое общее пространство с зеленью.\n\nОсновой строительства станет CLT: панели из перекрёстно склеенной древесины. Высокая степень заводской подготовки должна упростить сборку и сократить отходы. Это заявленные преимущества проектной системы; готовых эксплуатационных показателей у комплекса пока нет.\n\nМодульность касается и квартир. Планировки задуманы так, чтобы их можно было менять под разных жильцов, включая людей с ограниченной мобильностью. Со временем должно быть возможно перераспределять площади между жильём, совместной работой и общими зонами.\n\nВ проект заложены сквозное естественное проветривание, зелёные кровли, солнечные панели, сбор дождевой воды и повторное использование серой воды. Местным архитектором и консультантом по экологической стратегии выступает SOCOTEC Spain.\n\nSa Casa находится в разработке. Ценность предложения предстоит проверить строительством: особенно важно, насколько гибкая схема сохранится в реальных квартирах.`,'https://www.stefanoboeriarchitetti.net/project/sa-casa-ibiza-2/','Визуализация: Stefano Boeri Architetti · Изображение опубликовано designboom','sa-casa','Проект в разработке · Представлен в сентябре 2026');
add('red-submarine','Красная деревянная «подлодка» Wiki World стоит в лесу','architecture','Проект','Ухань, Китай','На 20 м² поместились гостиная с большим окном и спальное место под световым люком.',`Wiki World построили небольшой лесной дом Red Submarine Cabin. Его красная оболочка и круглые окна отсылают к подводной лодке, хотя здание стоит среди деревьев в Ухане.\n\nВ гостиной сделали большое видовое окно, а к спальному месту на верхнем уровне ведёт лестница. Над кроватью расположен световой люк. На площади 20 м² пространство развивается по вертикали: дневная зона и сон занимают разные уровни.\n\nКонструкция собрана из клеёной древесины. По описанию архитекторов, детали и соединения проектировали цифровым способом для полной заводской подготовки. Дом приподнят над землёй; команда сообщает, что при размещении сохранила деревья и бамбук на участке.\n\nПроект интересен как вариант небольшого сборного жилья, в котором характер возникает из формы и деталей. Круглые окна дополняют большой проём и задают разные способы смотреть наружу.\n\nДом датирован 2026 годом, публикация вышла 12 сентября. Экологические характеристики в описании принадлежат авторам проекта; независимая оценка воздействия на участок в источнике не приведена.`,'https://www.archdaily.com/1184634/red-submarine-cabin-wiki-world','Фото: Xhot · Проект: Wiki World · ArchDaily','red-submarine','Построено в 2026 · Публикация 12 сентября');
add('toad-house','В Сеуле новый ханок развернули к собственному двору','interiors','Проект','Сеул, Южная Корея','NOMAL и ONJIUM Housing Studio построили дом площадью 92 м² на сложном участке в Сочхоне.',`Участок Dookkuubi Jib имеет неправильную форму и длинный узкий «хвост». Окружение кажется жилым, но в соседних зданиях много кафе, ресторанов и гостевых домов. Заказчикам требовалось личное пространство внутри оживлённого района.\n\nNOMAL и ONJIUM Housing Studio перенесли вход на западную сторону, чтобы освободить южный двор и обращённое к нему общее пространство. Старый ханок был сильно переделан и повреждён: проект предполагал новое строительство, а не реставрацию.\n\nПри этом архитекторы сохранили логику размещения и движения, связанную с прежним домом. Дополнительный уровень помог обеспечить приватность. Площадь и объём подбирали так, чтобы не перегрузить небольшой участок.\n\nКультурная преемственность здесь выражена в устройстве повседневной жизни. Двор, направление входа и защищённость комнат оказываются не менее важными, чем узнаваемая крыша.\n\nДом завершён в 2026 году. В сентябрьской публикации можно подробно рассмотреть его в фотографиях Roh Kyung.`,'https://www.archdaily.com/1184854/dookkuubi-jib-toad-house-nomal-plus-onjium-housing-studio','Фото: Roh Kyung · Проект: NOMAL + ONJIUM Housing Studio · ArchDaily','toad-house','Построено в 2026 · Публикация 11 сентября');
add('malonic','Casa Malonic открывается к океану через круглый двор','interiors','Проект','Сиуатанехо, Мексика','HW-STUDIO выстроили маршрут от закрытого уличного фасада к свету, деревьям и морскому горизонту.',`Со стороны улицы Casa Malonic выглядит сдержанным белым объёмом. Изогнутая бетонная стена следует за дорогой и отделяет частное пространство. Океан раскрывается не сразу: сначала нужно пройти внутрь.\n\nМаршрут приводит в круглый двор, окружённый белыми стенами. Через большой вырез в объёме появляются небо и кроны деревьев. Дальше дом становится более открытым, а кровля создаёт тень над пространствами, обращёнными к побережью.\n\nАрхитекторы HW-STUDIO описывают отправную точку как простое укрытие от солнца и дождя. Цвет и фактура пола напоминают пляжный песок; белые стены соотносятся с цветущими деревьями на участке.\n\nВ этом проекте стоит смотреть не только на отдельные кадры. Его главный приём — последовательность: защищённая граница, внутренний двор, открытый горизонт. Именно движение связывает интерьер с ландшафтом.\n\nПлощадь дома — 497 м², год завершения — 2026. Фотографии Сесара Бехара опубликованы 10 сентября.`,'https://www.archdaily.com/1184892/casa-malonic-hw-studio','Фото: César Béjar · Проект: HW-STUDIO · ArchDaily','malonic','Построено в 2026 · Публикация 10 сентября');
add('chant','Ли Брум собирает из стеклянных блоков целые световые конструкции','lighting','Новость','Лондон, Великобритания','В Chant появились крупные люстры, линейные подвесы и соединения под прямым углом.',`Серия Chant выросла из отдельного светильника в семейство, которым можно организовать целый интерьер. На London Design Festival Ли Брум покажет The Chant Chambers — несколько пространств, посвящённых разным вариантам коллекции.\n\nНовые элементы соединяются под прямым углом. Из них можно создавать протяжённые линии и крупные квадратные композиции. К люстрам и переносной лампе добавились настенные светильники, линейные подвесы и более масштабные конструкции.\n\nБрум впервые представляет Chant в дымчатом стекле. Повторяющийся стеклянный модуль остаётся узнаваемым, но тёмная отделка меняет характер света и отсылает к интерьерам конца 1970-х.\n\nПервая версия Chant появилась в коллекции Divine Inspiration на миланской неделе дизайна 2022 года. Сентябрьское расширение показывает, как один понятный элемент может стать системой: важны уже не только форма лампы, но и расстояния между модулями, повороты, размер композиции.\n\nВыставка открывается 15 сентября в шоуруме на Rivington Street и продлится до 20 сентября. Вход свободный.`,'https://londondesignfestival.com/activities/the-chant-chambers','Chant, Lee Broom · Изображение из официальной программы London Design Festival','chant','15–20 сентября 2026');
add('ceramics','Школу керамики в Сан-Паулу построили вокруг света и небольших садов','interiors','Новость','Сан-Паулу, Бразилия','На участке шириной десять метров оставили место для зелёного входа и наружных зон отдыха.',`Vila da Saúde Studio занимает вытянутый участок размером 10 × 50 метров. Здание спроектировали Plareng и Consoante Arquitetura e Integração для школы керамики.\n\nЗаказчики хотели озеленённый вход. Поэтому архитекторы отодвинули корпус от улицы дальше, чем требовали местные нормы. Первое впечатление от школы формирует сад, через который посетители попадают внутрь.\n\nПланировку определили естественное освещение, сквозное проветривание и небольшие открытые площадки для отдыха. Для мастерской это практичные приоритеты: важно видеть материал при дневном свете и иметь возможность выйти из рабочего пространства.\n\nПлощадь здания — 813 м². Проект завершён в 2025 году, а новая публикация вышла 11 сентября 2026-го. Съёмка Lela Leme показывает, как учебное пространство устроено на узком городском участке.\n\nЭтот пример стоит сохранить тем, кто проектирует мастерские: качество подхода к зданию и короткие перерывы на воздухе здесь включены в архитектурную задачу с самого начала.`,'https://www.archdaily.com/1184841/vila-da-saude-studio-plareng-plus-consoante-arquitetura-e-integracao','Фото: Lela Leme · Проект: Plareng + Consoante · ArchDaily','ceramics','Построено в 2025 · Публикация 11 сентября 2026');
add('materials','Material Matters переезжает в Шордич: что смотреть на ярмарке материалов','materials','Обзор','Лондон, Великобритания','Биоматериалы, строительные отходы и новые способы производства — с 15 по 17 сентября.',`Пятая лондонская Material Matters пройдёт в UNLOCKED Shoreditch, бывшем промышленном здании на Curtain Road. Ярмарка впервые становится одним из опорных событий Shoreditch Design Week.\n\nВ программе заявлены Front и Biomason с кирпичами, плиткой и панелями, связанными с переработкой отходов. Carbon Cell разрабатывает компостируемый вспененный материал с биоуглём как альтернативу пластиковым пенам. The New Materialist работает на пересечении дизайна, науки и экологии.\n\nОтдельная выставка Matrix Design — Hand, Code, Matter — посвящена совместной работе ручного изготовления, рисунка и искусственного интеллекта. Рядом представлены финалисты Wood Awards и работы участников Only Natural Awards.\n\nЗдесь полезно смотреть на образцы вблизи: поверхность, кромка и способ соединения часто рассказывают о материале больше, чем рекламный тезис. Для применения в проекте затем потребуются технические данные производителя — огнестойкость, влагостойкость, срок службы и условия переработки.\n\nДаты: 15–17 сентября. Адрес: 118 Curtain Road. По информации организатора, посещение для профессионалов бесплатное, с предварительной регистрацией.`,'https://materialmatters.design/The-Fair','UNLOCKED Shoreditch — площадка ярмарки · Изображение организатора Material Matters','materials','15–17 сентября 2026');
add('wax','Четыре этажа WAX: новая мебель, трикотаж и свет','furniture','Обзор','Лондон, Великобритания','В бывшей викторианской фабрике встретились COZMO, TAMART, MINIMALUX и LIGHTMASS^.',`WAX 2026 объединяет четыре марки на четырёх этажах The Wax Building. Показ пройдёт с 15 по 20 сентября на Garden Walk в Шордиче.\n\nCOZMO представит кресло Ginkgo и столы Squarish Эрнста Бартолина Йенсена, а также столик Pac-Man Бена Маккарти. Ещё одна новинка — текстиль Raw Edges и BYBORRE: геометрический рельеф возникает непосредственно в структуре трёхмерного вязания.\n\nTAMART посвящает экспозицию свету за обеденным столом. В неё входят Clore Bead Pendant и модульный Clore Beam с выдувным непрозрачным стеклом. Отправной точкой стал торшер Тамар де Шалит начала 1960-х.\n\nНа третьем этаже LIGHTMASS^ от Raw Edges показывает новые настольные светильники. MINIMALUX собирает предметы и освещение в домашнюю композицию Working Objects, включая серии NIL и DRUM.\n\nПолучается удобный срез предметного дизайна: можно сравнить, как разные студии работают с мягкостью, каркасом, светом и поверхностью в одном здании. Вход свободный.`,'https://londondesignfestival.com/activities/wax-2026','WAX 2026 · Изображение The Wax Building из программы LDF','wax','15–20 сентября 2026');
const short=(...args)=>add(...args);
short('gradas','Sancal и UNS покажут кресло Gradas с текстилем BYBORRE','furniture','Коротко','Лондон','Новая модель объединяет предметный дизайн и объёмный текстиль.','В шоуруме Insidesource представят Gradas — кресло Sancal и UNS с тканью Eirene, разработанной BYBORRE совместно с UNS. Показ входит в программу 14–18 сентября. На 16 сентября назначена утренняя встреча о дизайне и сотрудничестве с участием Raw Edges. Условия участия опубликованы организатором.','https://londondesignfestival.com/activities/elevating-experiences-through-design-collaboration','Шоурум Insidesource · Изображение организатора в программе LDF','gradas','14–18 сентября 2026');
short('medals','Джонатан Андерсон, Анаб Джайн и ещё два лауреата London Design Medals','people','Коротко','Лондон','Награды этого года охватывают моду, образование и инклюзивный дизайн.','Лауреатами London Design Medals 2026 стали Jonathan Anderson, Christopher Frayling, Anab Jain и Solveiga Pakštaitė. Объявление опубликовано 9 сентября; церемония назначена на 14 сентября в RH London. Состав показывает, насколько широко фестиваль понимает профессию дизайнера.','https://www.wallpaper.com/design-interiors/design-events/london-design-medals-2026','Изображение предоставлено London Design Festival · Wallpaper*','medals','Лауреаты объявлены 9 сентября 2026');
short('open-house','Более 600 лондонских зданий открывают двери на Open House','exhibitions','Коротко','Лондон','В программе — частные дома, архивы и известные общественные здания.','Open House London проходит 12–20 сентября. В числе мест программы — архив Zaha Hadid Foundation, Lloyd’s of London и оранжерея Barbican. Возможность попасть внутрь и правила бронирования зависят от конкретного объекта: маршрут лучше составлять по официальным карточкам посещения.','https://www.wallpaper.com/architecture/architecture-events/2026-london-open-house-festival-uk','Фото: National Trust Images / Megan Taylor · Open House · Wallpaper*','open-house','12–20 сентября 2026');
short('reading-room','В Бромптоне открывается временная библиотека о квир-дизайне','people','Коротко','Лондон','The Reading Room — часть программы куратора Алекса Тиги-Уокера.','В рамках Brompton Design District Алекс Тиги-Уокер представляет The Reading Room — временную библиотеку, посвящённую квир-дизайну, творчеству и культурной истории. Адрес — 36 Thurloe Place. Проект входит в программу района с темой Perfectly Imperfect, обращённой к экспериментам и процессу создания вещей.','https://www.wallpaper.com/design-interiors/london-design-festival-brompton-reading-room-alex-tieghi-walker-books','The Reading Room · Пресс-изображение · Wallpaper*','reading-room','London Design Festival · сентябрь 2026');
short('radford','Современная мебель встретится с архивными коврами Christopher Farr','objects','Коротко','Лондон','Progressive Permanence — совместная выставка с Max Radford Gallery.','Max Radford Gallery и Christopher Farr соединяют современную мебель с коврами по архивным дизайнам. Выставка Progressive Permanence пройдёт 15–20 сентября в пространстве Christopher Farr по адресу 18 Calvin Street. Хороший повод посмотреть, как предметы разных поколений работают вместе в одном интерьере.','https://www.wallpaper.com/design-interiors/max-radford-christopher-farr-london-design-festival-2026','Фото: Edward Rollitt · Progressive Permanence · Wallpaper*','radford','15–20 сентября 2026');
short('buenos-aires','Архитектурная биеннале Буэнос-Айреса готовит пять недель бесплатной программы','exhibitions','Коротко','Буэнос-Айрес','Около ста бюро и пятнадцать выставок — к сорокалетию биеннале.','Юбилейная биеннале посвящена теме HABITAR — «обитать». С 22 сентября и в течение октября организаторы запланировали выставки, инсталляции и встречи. Заявлены около 100 архитектурных бюро, 15 выставок и 50 конференций, с участниками более чем из 55 городов. Программа свободная и бесплатная.','https://www.archdaily.com/1184927/buenos-aires-architecture-biennial-celebrates-40-years-with-a-free-program-under-the-theme-of-inhabiting','Quipu, Gonzalez Moix Arquitectura · Изображение предоставлено биеннале через ArchDaily','buenos-aires','Начало 22 сентября 2026');
short('carbon-cell','Carbon Cell разрабатывает компостируемую пену с биоуглём','materials','Коротко','Лондон','Материал заявлен в программе Material Matters как альтернатива пластиковым пенам.','Carbon Cell участвует в Material Matters 15–17 сентября. Компания работает над компостируемым вспененным материалом с биоуглём. Пока это описание разработки: применимость к конкретной упаковке или изделию нужно проверять по техническим условиям производителя.','https://londondesignfestival.com/activities/material-matters','','','15–17 сентября 2026');
short('biomason-front','Front и Biomason привезут строительные материалы из отходов','materials','Коротко','Лондон','Кирпичи, плитка и панели в программе Material Matters.','На Material Matters заявлены Front и Biomason с кирпичами, плиткой и панелями на основе отходов. Организаторы включили их в раздел новых подходов к строительству и повторному использованию ресурсов. Показ пройдёт в UNLOCKED Shoreditch.','https://londondesignfestival.com/activities/material-matters','','','15–17 сентября 2026');
short('lovspark','Matrix Design покажет, как соединить ручную работу, рисунок и ИИ','technology','Коротко','Лондон','Hand, Code, Matter проходит на Material Matters.','Выставка Matrix Design посвящена взаимодействию ремесла и цифрового проектирования. По информации Material Matters, здесь представят новую платформу Lovspark с использованием ИИ. Название показа — Hand, Code, Matter: A New Flow for Spatial Design.','https://materialmatters.design/The-Fair','','','15–17 сентября 2026');
short('sender-unknown','Азиза Кадыри рассматривает узбекскую вышивку через вопрос об ИИ','technology','Коротко','Лондон','Sender Unknown отвечает на коллекцию сюзане музея V&A.','Азиза Кадыри обращается к сюзане — традиционной вышивке Узбекистана — и спрашивает, что происходит с культурным контекстом при заимствовании образов алгоритмами. Работа Sender Unknown показана в зале 42 V&A. Это художественное исследование, а не демонстрация технологии сохранения наследия.','https://www.vam.ac.uk/articles/vampa-x-london-design-festival-awakenings-trail','','','Программа V&A Awakenings · сентябрь 2026');
short('playfool-server','В V&A посетителям предлагают почистить сервер','technology','Коротко','Лондон','Playfool обращает внимание на ручной труд за цифровой инфраструктурой.','Инсталляция The Server предлагает посетителям по очереди очищать объект. Движения отслеживаются и отображаются на печатных листках. Playfool связывает повседневный уход за музейными вещами с обслуживанием инфраструктуры ИИ. Работа находится в Photography Centre, зал 108.','https://www.vam.ac.uk/articles/vampa-x-london-design-festival-awakenings-trail','','','Программа V&A Awakenings · сентябрь 2026');
short('rca-inresponse','Тридцать выпускников RCA показывают дизайн как исследование','objects','Коротко','Лондон','Выставка InResponse входит в программу Brompton Design District.','Тридцать выпускников магистратуры Design Products Королевского колледжа искусств участвуют в InResponse. Экспозиция построена вокруг трёх направлений — ECHO, MATTER и SYNC. Они связывают предметы с памятью, материалом и человеческим телом. Объявление колледжа вышло 9 сентября.','https://www.rca.ac.uk/news-and-events/news/royal-college-of-art-announces-dynamic-line-up-for-london-design-festival-2026/','','','London Design Festival · 12–20 сентября 2026');
short('paris-hanji','В Париже дизайнеры работают с корейской бумагой ханджи','exhibitions','Коротко','Париж','Hanjimania проходит в Hôtel de la Marine.','Шесть участников, среди которых Constance Guisset, Studio KO и Harry Nuriev, создали предметы с мастерами корейской бумаги. Выставка Hanjimania знакомит с ханджи через современный дизайн. Ещё одно парижское открытие недели — первый шоурум Jieldé в XI округе.','https://www.lemonde.fr/en/lifestyle/article/2026/09/10/paris-design-week-three-surprising-highlights_6757364_37.html','','','Paris Design Week · сентябрь 2026');
short('bocci-labyrinth','Bocci и Бетан Лора Вуд показывают фиолетовый свет в декорациях «Лабиринта»','lighting','Коротко','Лондон','Новый цвет переносного 14p стал частью инсталляции Labyrinth Dreams.','Бетан Лора Вуд создала для Bocci инсталляцию, вдохновлённую фильмом «Лабиринт» с Дэвидом Боуи. В ней используется фиолетовая версия светильника 14p. Показ проходит 12–20 сентября на Bateman Street, 15.','https://www.wallpaper.com/design-interiors/lighting-designs-at-london-design-festival-2026','','','12–20 сентября 2026');
add("community-house","В Бельгии построили социальное жильё, которое выглядит как стопка разноцветных домов","architecture","Главная история","Кнокке-Хейст, Бельгия","Jakob+MacFarlane собрали 100 квартир, библиотеку, муниципальные службы и магазины в одном 15-этажном здании у городской площади.",`На бельгийском побережье появился довольно редкий тип жилой башни: она не пытается выглядеть одной большой башней. Jakob+MacFarlane разбили объём Community House на цветные террасы и небольшие «домики», поставленные друг на друга. Architectural Record опубликовал новые фотографии проекта 14 сентября.

Внутри — 100 квартир, библиотека, муниципальные службы, магазины, многофункциональный зал и общественные пространства. Проект занимает 15 уровней и около 15 200 м², а вокруг здания сформировано примерно 19 000 м² общественного пространства с рынком, площадками и зеленью. Это важно: жильё здесь не отделено от города отдельным стилобатом и шлагбаумом, а буквально стоит над повседневными городскими функциями.

Архитекторы объясняют форму двумя местными образами. Первый — невысокие дома бельгийского побережья. Второй — соседний порт Антверпен-Брюгге и его контейнеры. Отсюда и цветные алюминиевые фасады, и ощущение сложенной конструкции. На жилых уровнях предусмотрены общие теплицы и места встреч.

Для российской практики здесь полезна не яркая палитра сама по себе. Интереснее схема: плотное жильё можно проектировать не как изолированный жилой объект, а как кусок города, в котором библиотека, сервисы и обычные магазины работают каждый день. И ещё один урок — большой объём можно дробить не декоративными полосами на фасаде, а реальными террасами, общими пространствами и разной глубиной этажей.`,"https://www.architecturalrecord.com/articles/18403-snapshot-jakobmacfarlane-designs-a-colorful-vertical-village-on-the-belgian-coast","Фото: Roland Halbe · Проект: Jakob+MacFarlane · Источник: Architectural Record","community-house","Новая публикация проекта — 14 сентября 2026","2026-09-15");
add("all-straw","Этот дом почти целиком сделан из соломы. Она здесь и стена, и утеплитель, и отделка","materials","Главная история","Гудзон-Вэлли, США","LTL Architects и Guy Nordenson and Associates собрали маленький дом из сильно спрессованных соломенных плит вместо обычного многослойного пирога стены.",`All Straw House выглядит немного как маленькое лесное существо: высокий силуэт, густая соломенная оболочка и пять окон. Но интереснее всего то, чего снаружи почти не видно. Основные стены собраны не из тюков, а из заводских плит из спрессованной соломы.

Плиты режут на полосы и складывают горизонтальными слоями. В этой конструкции один материал выполняет сразу три функции: несёт нагрузку, утепляет и остаётся готовой внутренней поверхностью. В доме 111 слоёв соломенных панелей; через каждые 22 слоя стоят деревянные кольцевые балки для пространственной жёсткости. Снаружи — 33 сборные кассеты из камышовой кровли, работающие как толстый дождевой экран.

Прототип площадью около 13,5 м² изготовили модулями в Принстоне и за два дня собрали на участке рядом с Гудзоном. Architectural Record пишет, что это первое применение таких плит в сложенной несущей системе, поэтому команда отдельно испытывала материал на сжатие и изгиб. По расчётам авторов, оболочка даёт сопротивление теплопередаче около R-32; сами проектировщики оценивают запасённый в конструкции углерод примерно в 10,5 тонны CO₂-эквивалента. Эти цифры относятся именно к экспериментальному дому и не превращают технологию автоматически в готовый массовый продукт.

Для нас интересен принцип. Обычно стена — это длинный список слоёв, поставщиков и узлов. Здесь команда пытается убрать часть этого списка и заставить один биоматериал работать сразу в нескольких ролях. В России солома как сырьё точно не экзотика. Вопрос не в том, можно ли повторить этот дом буквально, а в том, появятся ли у нас сертифицированные панели, понятные узлы влаги и огня и нормальная индустриальная цепочка вокруг сельхозотходов.`,"https://www.architecturalrecord.com/articles/18372-in-new-yorks-hudson-valley-a-diminutive-shelter-made-of-straw-offers-a-new-way-of-building","Фото: Michael Moran / Otto · Проект: LTL Architects + Guy Nordenson and Associates · Источник: Architectural Record","all-straw","Подробная публикация — 14 сентября 2026","2026-09-15");
add("devils-milk","Шахар Ливне сделала мебель из истории каучука — и история там совсем не безобидная","objects","Новость","Эйндховен, Нидерланды","В серии The Devil’s Milk три предмета объясняют, как обычный каучук связан с колониальной добычей, трудом и промышленностью.",`Каучук настолько привычен, что мы почти не замечаем его как материал. Дизайнер Шахар Ливне решила сделать обратное: заставить предметы показывать не только свойства резины, но и историю её добычи. Проект The Devil’s Milk состоит из весов, шкафа и скамьи.

Весы отсылают к старой практике оценки сырого латекса по весу и одновременно к трудовым нормам на плантациях. В шкафе использована древесина каучуковых деревьев, которые уже перестали давать латекс. Его орнаменты выглядят декоративно, пока дверцы не открываются: внутри рисунок меняется и превращает спокойную поверхность в рассказ о разрыве и эксплуатации.

Здесь хороший урок для предметного дизайна. «История материала» часто остаётся абзацем в каталоге, который можно убрать — и предмет ничего не потеряет. У Ливне смысл встроен в конструкцию, старение поверхности, выбор древесины и сам тип предмета. Поэтому проект работает даже до того, как прочитаешь длинное описание.

Для интерьерной практики это полезный ориентир: если вы хотите говорить о происхождении материала, лучше искать способ сделать происхождение видимым в детали, соединении или поверхности, а не просто добавлять табличку со словом «осознанность».`,"https://www.stirworld.com/see-features-designer-shahar-livne-examines-the-violence-of-rubber-in-the-devil-s-milk-triptych","Фото: Barbara Medo · Проект: Shahar Livne · Источник: STIRworld","devils-milk","Публикация проекта — 14 сентября 2026","2026-09-15");
add("lobjet-mccormack","Ювелир Джессика Маккормак сделала посуду так, будто это украшения для стола","objects","Новость","Лондон / Нью-Йорк","В первой совместной коллекции L’OBJET и Jessica McCormack раковины, канаты и спирали не нарисованы сверху — из них сделана сама форма предметов.",`У морской темы в декоре есть известная опасность: ещё немного ракушек — и интерьер начинает напоминать сувенирную лавку на набережной. В совместной коллекции L’OBJET и ювелира Джессики Маккормак эту проблему решили довольно умно: морские мотивы используют не как картинку, а как конструкцию.

Раковина становится чашей, витой канат — ручкой ведра для льда, спираль — опорой зеркала. В коллекции есть блюда, чаши, ведра для шампанского, зеркало, предмет для икры и первая в истории L’OBJET серия столовых приборов. Тонкий фарфор соединён с ручной росписью 24-каратным золотом и металлическими деталями.

Самая удачная часть — столовые приборы. Здесь ювелирный масштаб действительно имеет смысл: предмет постоянно лежит в руке, поэтому важны вес, свет на металле и то, как мелкая деталь ощущается пальцами. Это хороший пример того, как сотрудничество с дизайнером из другой области даёт не просто новую графику, а новый способ думать о функции.

В работе с интерьером принцип легко перенести: орнамент сильнее, когда он что-то делает. Ручка, кромка, соединение или опора могут нести характер вещи лучше, чем нанесённый сверху рисунок.`,"https://design-milk.com/lobjet-jessica-mccormack-collaboration/","Фото предоставлено L’OBJET · L’OBJET × Jessica McCormack · Источник: Design Milk","lobjet-mccormack","Коллекция опубликована 14 сентября 2026","2026-09-15");
add("socialist-hotels","В одной книге собрали 153 социалистических отеля — пока их не переделали до неузнаваемости","architecture","Новость","31 страна","Фотограф Елена Амабили несколько лет снимала гостиницы Восточной Европы и постсоветского пространства. Получился каталог архитектуры отдыха, которая быстро исчезает.",`FUEL выпускает книгу Socialist Hotels фотографа Елены Амабили. В ней 153 гостиницы из 31 страны — от небольших домов отдыха до огромных курортных комплексов. Это не подборка самых красивых зданий эпохи, а попытка зафиксировать целый тип архитектуры до того, как его окончательно перестроят или снесут.

Амабили снимала не только фасады. В книге есть номера, холлы, светильники, ковры, вывески и мебель — всё то, что обычно исчезает первым во время «осовременивания». Именно интерьеры часто лучше всего показывают, как гостиница задумывалась: как массовый отдых, государственная репрезентация или почти домашний пансион.

Для российской профессиональной среды эта книга особенно интересна. У нас огромное количество зданий того же периода проходят ремонт без нормальной фиксации оригинальных деталей. Старый светильник или стойка администратора часто воспринимаются как мусор просто потому, что им 40 лет. Через десять лет восстановить эту картину по памяти уже невозможно.

Практический вывод простой: перед реконструкцией стоит фотографировать не только фасад и планы. Снять дверные ручки, мебель, таблички, свет, рисунок ковролина и типовые номера — дёшево. А потом уже решать, что сохранять. Иногда хорошая документация оказывается ценнее поспешной попытки оставить всё подряд.`,"https://www.wallpaper.com/architecture/socialist-hotels-is-fuel-publishings-newest-study-of-a-fast-vanishing-design-aesthetic","Изображение: FUEL Publishing · Фото в книге: Elena Amabili · Источник: Wallpaper*","socialist-hotels","Книга выходит в сентябре 2026 · Свежая публикация 14 сентября","2026-09-15");
short("vatican-diluvium","JR накрыл фасад Ватиканской библиотеки 70-метровой волной","exhibitions","Коротко","Ватикан","Diluvium открывает пятилетний цикл выставок о том, что может уничтожить библиотечное наследие — от воды до человеческого вмешательства.",`14 сентября Ватиканская апостольская библиотека открыла выставку AQVA — первый выпуск пятилетнего цикла Catastrophe and Wonder. Главный внешний жест — Diluvium французского художника JR: чёрно-белая волна длиной около 70 метров проходит по фасаду библиотеки и отсылает к изображению Всемирного потопа Гюстава Доре. Внутри вода рассматривается сразу в двух ролях: как угроза книгам и как инструмент реставрации. В проекте также участвуют типограф Билл Моран и шеф Фульвио Пьеранджелини. Для посетителей выставка откроется 25 сентября и продлится до 14 мая 2027 года.`,"https://www.vaticannews.va/de/papst/news/2026-09/bibliothek-vatikan-apostolisch-papst-leo-xiv-buecher-kultur.html","","","Открытие — 14 сентября 2026","2026-09-15");
short("sottsass-glass","В Париже показывают 27 стеклянных работ Этторе Соттсасса 1998 года","exhibitions","Коротко","Париж, Франция","Серии Esercizi и Capricci напоминают, насколько свободно Соттсасс обращался с цветом и масштабом даже в поздних работах.",`Domus 14 сентября опубликовал новый обзор парижской выставки 27 стеклянных объектов Этторе Соттсасса из серий Esercizi и Capricci. Работы были сделаны в 1998 году с муранским стеклом: прозрачные и непрозрачные объёмы собраны на тонких металлических стойках почти как архитектурные модели. Полезно смотреть на них не только как на коллекционный дизайн. Здесь хорошо видно, как несколько простых геометрий, цвет и разрыв масштаба могут дать предмету характер без декоративной перегрузки.`,"https://www.domusweb.it/en/news/gallery/2026/09/14/ettore-sottsass-murano-glass-paris-exhibition.html","","","Свежая публикация — 14 сентября 2026","2026-09-15");
add("radar-one-material","Что мы увидели раньше рынка: один материал всё чаще пытаются заставить делать три работы","materials","Radar","Наблюдение редакции","Конструкция, утепление и готовая поверхность начинают сходиться в одной системе. All Straw House — особенно наглядный пример.",`Сейчас в новых материалах повторяется один интересный ход: убрать лишние слои. Не сделать ещё одну красивую облицовку, а найти материал, который одновременно несёт, изолирует и может остаться видимым.

All Straw House доводит эту логику почти до буквальности. Сильно спрессованная солома работает как несущая стена, теплоизоляция и внутренняя отделка. На Material Matters в Лондоне мы видим соседний процесс: разработчики пытаются превратить отходы, биоуголь и минеральные составы не в декоративный «эко-образец», а в полноценные строительные панели, блоки и заполнители.

Пока рано объявлять это новой нормой. Между выставочным образцом и реальной стеной стоят пожарные испытания, влажностный режим, ремонтопригодность, сертификация и цена. Но направление стоит запомнить: следующий этап устойчивого материала может быть не в том, что он «зелёнее» одного привычного слоя, а в том, что позволяет вообще убрать два соседних.

Для российского рынка это особенно интересно там, где сырьё дешёвое и локальное — сельхозотходы, древесные остатки, минеральное вторсырьё. Если технология сокращает количество операций и поставщиков, экологический аргумент наконец начинает совпадать с обычной экономикой стройки.`,"https://ltlarchitects.com/all-straw-house","Фото: Michael Moran / Otto · Проект: LTL Architects + Guy Nordenson and Associates","all-straw","Наблюдение TECTONICA · 15 сентября 2026","2026-09-15");
add("loyco-chile","В Чили построили дом у озера, похожий на сельский ангар — и это не случайность","architecture","Главная история","Озеро Вичукен, Чили","CCRA Arquitectura взяла знакомую для региона форму хозяйственных построек, подняла дом над влажным грунтом и оставила деревянные фермы главным элементом интерьера.",`LoyCo House стоит у озера Вичукен, недалеко от тихоокеанского побережья Чили. Архитекторы Ricardo Atanacio и Carolina Contreras из CCRA Arquitectura не стали делать из загородного дома отдельный дизайнерский объект. Они посмотрели на сельские постройки вокруг и взяли оттуда простую геометрию, деревянную обшивку и крупные клеёные фермы.

Дом собран по Г-образной схеме вокруг внутреннего двора и двух садов. На первом уровне находятся общие пространства и четыре спальни, выше — ещё две спальни и семейная зона. Верхняя часть сделана из дерева, а основание немного поднято над землёй: это помогает держать жилые помещения дальше от воды при возможных подтоплениях.

Самое удачное здесь — конструкцию не пришлось потом «оформлять». Клеёные фермы остаются видимыми и задают ритм фасаду, террасам и внутренним пространствам. Дерево снаружи должно стареть естественно, а простая форма действительно напоминает местные сельскохозяйственные здания, а не стилизуется под них декоративными деталями.

Для российской практики это хороший пример того, как можно работать с загородным домом без набора дорогих эффектов. Поднятое основание решает вопрос влаги, открытая конструкция одновременно работает и как архитектура, а местный тип здания даёт проекту характер без буквального «народного стиля».`,"https://www.wallpaper.com/architecture/residential/chilean-holiday-home-loyco-ccra","Фото: Aryeh Kornfeld · Проект: CCRA Arquitectura · Источник: Wallpaper*","loyco-chile","Публикация проекта — 15 сентября 2026","2026-09-16");
add("anamesa-mykonos","K-Studio почти спрятала дом на Миконосе в склоне — море осталось главным видом","architecture","Главная история","Миконос, Греция","Anamesa врезан в каменистый склон над пляжем Калафатис: каменные стены, известковая отделка и дерево связывают дом с островом без декораций «под Грецию».",`На восточной стороне Миконоса, подальше от самой шумной части острова, K-Studio построила частный дом Anamesa. Название переводится примерно как «между»: дом должен одинаково хорошо работать и для спокойной жизни, и для большой компании.

Основные объёмы частично заглублены в склон. Каменные подпорные стены продолжают рельеф, местная растительность подходит почти вплотную к дому, а из жилых пространств открываются длинные виды на Эгейское море. Внутри есть отдельные спальни-сьюты, сервисные и велнес-зоны; наружные пространства собираются вокруг нескольких самостоятельных мест — от обеденной зоны до круглой площадки с огнём.

Палитра предельно короткая: камень, известка, дерево. Большую часть деталей делали местные мастера. Поэтому характер Миконоса появляется не через синие ставни и цитаты из открыток, а через массу стены, тень, переходы между улицей и комнатой и то, как здание сидит на каменистом участке.

Для тёплых регионов России здесь полезнее всего не стиль, а климатическая логика: часть объёма уходит в грунт, переходные зоны дают тень, тяжёлые каменные поверхности работают вместе с открытыми пространствами. Такой подход делает интерьер спокойнее ещё до выбора мебели.`,"https://www.wallpaper.com/architecture/residential/anamesa-k-studio-mykonos-house-greece","Фото: Ana Santl · Проект: K-Studio · Источник: Wallpaper*","anamesa-mykonos","Публикация проекта — 15 сентября 2026","2026-09-16");
add("musashi-koyama","В Токио дом для четверых уместили на участке 39,5 м². Полы закрутили спиралью","architecture","Новость","Токио, Япония","Tato Architects отказались от обычных двух этажей и разбили дом на четыре сдвинутых уровня, связанные взглядами и короткими лестницами.",`House in Musashi-Koyama стоит на флажковом участке площадью всего 39,53 м² в плотном жилом районе Токио. Внутри должна жить семья из четырёх человек. Самый очевидный вариант — два обычных этажа — архитекторы Tato Architects / Yo Shimada отбросили: комнаты получались слишком маленькими и изолированными.

Вместо этого пол разделили на четыре части и подняли их по спирали. Получилась цепочка уровней, откуда постоянно видны пространства выше и ниже. В плане дом всё равно остаётся очень маленьким — общая площадь 47,14 м², — но глаз не упирается в отдельную комнату.

Ещё интереснее конструкция. Перекрытия держат LVL-балки толщиной 30 мм и тонкие стальные элементы, сопоставимые по масштабу с перилами. Архитекторы сознательно не хотели, чтобы несущая система выглядела тяжелее мебели. Окна тоже работают как маленькие дополнительные комнаты: северный эркер становится сиденьем у парка, кухонный — хранением и источником света, наверху есть фонарь и выход на кровлю.

Для компактных квартир и домов в России отсюда можно забрать две вещи. Первая — перепад пола иногда даёт больше пространственных связей, чем перегородка. Вторая — в маленьком объёме толщину видимых конструкций стоит проектировать так же внимательно, как мебель: лишние десять сантиметров визуальной массы там действительно имеют значение.`,"https://www.designboom.com/architecture/spiral-timber-beams-steel-tiny-40-sqm-tokyo-home-musashi-koyama-tato-architects-yo-shimada/","Фото: Shinkenchiku-sha · Проект: Tato Architects / Yo Shimada · Источник: designboom","","Публикация проекта — 15 сентября 2026","2026-09-16");
add("feldspar-lighting","Feldspar сделала фарфоровые плафоны настолько тонкими, что они светятся насквозь","furniture","Новость","Девон, Великобритания","Первая коллекция света британской студии использует костяной фарфор не как непрозрачный корпус, а как полупрозрачный материал для мягкого тёплого света.",`Студия Feldspar, которую ведут Jeremy и Cath Brown, выпустила первую полноценную коллекцию света: четыре подвеса и две настольные лампы. Главный материал — тонкий костяной фарфор. Днём он выглядит почти непрозрачным белым, а после включения начинает пропускать тёплый свет и становится похож на плотную бумагу.

Самая сложная часть была технической: подвесные плафоны нужно было отливать достаточно тонкими для свечения, но не настолько тонкими, чтобы они теряли прочность. У настольных ламп основания толще, а тканевые абажуры вручную делает Eloise Scotland; внутри спрятано кобальтово-синее ребро, а яркость регулируется небольшим латунным диммером.

Вещи получились очень спокойными, но в них нет ощущения безликой «минималистичной лампы». Материал меняется при включении, на поверхности остаётся фирменная вмятина Feldspar, а керамика, ткань и металл ощущаются рукой по-разному.

Для проектировщика света здесь полезна простая мысль: толщина материала — это тоже светотехнический параметр. Иногда характер прибора можно получить не сложной оптикой и декоративным рисунком, а точной толщиной оболочки и тем, как она ведёт себя при двух состояниях — выключено и включено.`,"https://www.wallpaper.com/design-interiors/interior-design/lighting/feldspar-lighting-collection","Фото: Courtesy of Feldspar · Проект: Feldspar · Источник: Wallpaper*","feldspar-lighting","Коллекция представлена 15 сентября 2026","2026-09-16");
add("deoron-berlin","В Берлине 65 дизайнеров заняли старый спиртзавод — и сделали выставку, где хотелось задержаться","exhibitions","Новость","Берлин, Германия","Deoron собрал мебель, свет, стекло и технику в бывшем заводе Monopol и отказался от привычной схемы «стенд — предмет — следующий стенд».",`Платформа Deoron провела в Берлине свой третий офлайн-проект. Более 65 дизайнеров, брендов и независимых студий заняли три этажа бывшего спиртзавода Monopol 1899 года постройки — около 900 м² пространства, которое само по себе уже задаёт выставке характер.

Предметы не разложили по отраслевым секциям. Мебель, свет, стекло, техника и небольшие объекты собирались в общие интерьерные сцены. В центре стояла большая звуковая система Atelier d’Ingénierie Fades и New Fidelity; вокруг проходили прослушивания и живые выступления. Там же работал винный бар, поэтому публика могла не пробежать выставку за двадцать минут, а остаться.

Для Deoron это логичное продолжение пути: проект начинался как Instagram-аккаунт, вырос в онлайн-платформу, каталог и агентство, а теперь делает физические события. И это, пожалуй, самое интересное в истории: цифровая витрина не заменила офлайн, а создала аудиторию, которой захотелось встретиться с предметами вживую.

Для российских шоурумов и выставок здесь прямой урок. Люди дольше взаимодействуют с продуктом, когда вокруг него есть нормальная среда — звук, еда, разговор, место посидеть, сценарий движения. Иногда это работает сильнее, чем ещё один баннер с характеристиками.`,"https://www.wallpaper.com/design-interiors/design-events/deoron-berlin-2026-review","Фото: Mariona Calathea · Deoron Berlin / Monopol · Источник: Wallpaper*","deoron-berlin","Итоги берлинского проекта опубликованы 15 сентября 2026","2026-09-16");
add("tallinn-how-much","Таллиннская биеннале считает не цену стройки, а полный счёт за архитектуру","exhibitions","Новость","Таллинн, Эстония","Тема TAB 2026 — «How Much?»: к смете добавляют обслуживание, ресурсы, труд, экологические последствия, снос и даже цену затянувшегося бездействия.",`В Таллине идёт восьмая архитектурная биеннале TAB 2026. Её вопрос звучит почти бытово — «Сколько?» — но кураторы предлагают считать не только стоимость квадратного метра на момент сдачи. В расчёт попадают ресурсы, труд, эксплуатация, обслуживание, экологические последствия и то, что произойдёт со зданием дальше.

Главная выставка расположена в Linnahall — огромном бетонном комплексе на набережной, построенном к Олимпиаде 1980 года и много лет почти не используемом. Получился очень точный экспонат: реконструкция дорогая, снос тоже дорогой, а ничего не делать — значит каждый год накапливать ещё один вид расходов.

В программе есть и более предметные ответы. Например, павильон Resonance от Aru Ma- Architects собран из арматуры, каната, известняка и фанеры. Задача была не показать «бедную архитектуру», а проверить, можно ли получить пространственное качество при жёстком бюджете.

Для российской практики тема болезненно прикладная. Когда проект сравнивают только по стартовой смете, дешёвое решение легко оказывается дорогим через пять лет. TAB предлагает смотреть на стоимость как на жизненный цикл — и для фасада, общественного здания или жилого комплекса это гораздо честнее, чем одна цифра в тендере.`,"https://www.archdaily.com/1185112/tallinn-architecture-biennale-2026-explores-the-true-cost-of-architecture-through-how-much","Фото: Martin Siplane / Rene Suurkaev · TAB 2026 · Источник: ArchDaily","","Материал опубликован 15 сентября 2026; биеннале идёт до 30 ноября","2026-09-16");
add("lasvit-herbarium","Lasvit отпечатала настоящие растения в стекле — и собрала из них светильник для дома в Напе","furniture","Новость","Напа-Вэлли, США","Растения кладут под горячее стекло, и их рельеф остаётся в каждом кристаллическом элементе. Система модульная, поэтому композицию можно масштабировать под конкретное пространство.",`Lasvit сделала для частного дома в Напа-Вэлли световую инсталляцию из серии Herbarium. Технология очень буквальная: мастера собирают и высушивают растения, а затем льют на них горячее стекло. Органика сгорает, но её фактура остаётся отпечатанной в поверхности богемского хрусталя.

Получается редкое сочетание повторяемости и случайности. Базовый элемент можно производить серией, но рисунок каждого плафона всё равно немного другой, потому что реальный лист или стебель не повторяется. Проект создан под творческим руководством Mária Čulenová.

Herbarium интересен ещё и как система, а не как один эффектный заказ. Модули можно собирать в разные по размеру композиции — от жилого интерьера до большого общественного пространства.

Для интерьерной практики это хороший приём: если дорогой индивидуальный объект нужно масштабировать, не обязательно делать каждую деталь уникальной. Можно стандартизировать узел и крепление, а вариативность оставить внутри материала. Тогда ручная работа остаётся видна, а проект не превращается в полностью штучное производство.`,"https://www.designboom.com/design/lasvit-lighting-fixture-installation-for-napa-valley-home/","Изображения: courtesy of Lasvit · Проект: Lasvit Herbarium · Источник: designboom","","Проект опубликован 15 сентября 2026","2026-09-16");
add("bower-nyc","В Нью-Йорке поставили надувной навес ради тени. Его собирают за день без спецтехники","architecture","Новость","Нью-Йорк, США","The Bower от Elsa Ponce — временная городская тень для Summer Streets: лёгкая конструкция, надувная крона и мел, которым посетители обводят меняющиеся пятна света.",`Летом Нью-Йорк перекрывает часть улиц для программы Summer Streets, и в этом году городской департамент транспорта заказал дизайнеру Elsa Ponce временный навес The Bower. Он появился на Park Avenue и Foley Square и должен был решить очень простую задачу: дать людям место посидеть в тени там, где деревьев недостаточно.

Вместо капитального павильона команда сделала группу надувных розово-сиреневых элементов. Их форма отсылает к пятнам света под кроной дерева, а цвет — к жакаранде. Конструкцию можно установить и убрать за один день небольшой командой без специальной техники.

На земле оставили мел. Посетители обводили границы падающей тени, и по мере движения солнца на покрытии появлялся коллективный рисунок. То есть навес не только защищал от жары, но и показывал, как тень меняется в течение дня.

Для российских городов идея очень практичная. Летняя тень не обязана начинаться с фундамента, металлокаркаса и долгого согласования капитального объекта. Для фестивалей, набережных и временно пешеходных улиц лёгкая сезонная конструкция может быть быстрее, дешевле и интереснее — при условии, что заранее решены ветер, огнестойкость и безопасность креплений.`,"https://www.designboom.com/architecture/pink-inflatable-canopy-soft-shade-new-york-streetscape-elsa-ponce-bower/","Фото: Carlos Galek Sefchovich · Проект: Elsa Ponce / NYC DOT Art Program · Источник: designboom","","Проект опубликован 15 сентября 2026","2026-09-16");
short("pokeball-hokkaido","В Хоккайдо сделали гостиничный номер внутри гигантского покебола","interiors","Коротко","Хоккайдо, Япония","Pokémon Sleep и NOT A HOTEL превратили знакомую сферу в маленький номер с круглой кроватью и окном в лес. Это временная кампания, а не новый гостиничный стандарт.",`Pokémon Sleep вместе с японской NOT A HOTEL построили на Хоккайдо увеличенный Poké Ball, внутри которого можно переночевать. В сферу уместили круглую кровать для двоих, окно на природу и экран над кроватью. Проект сделан как ограниченная кампания, поэтому интереснее здесь не тема Pokémon сама по себе, а дисциплина: один узнаваемый образ довели до реального пространственного опыта, не пытаясь декорировать под него целый отель.`,"https://www.designboom.com/design/giant-poke-ball-human-sized-sleeping-pod-japan/","Проект: Pokémon Sleep × NOT A HOTEL · Источник: designboom","","Проект опубликован 15 сентября 2026","2026-09-16");
